/**
 * 분해 막대의 방식·방향 고르기와 단계 표시, 장면마다 분해 계획(첫 화면 JS 밖 — 분해 계산 explode.ts와 함께 문서를 열 때 받는다).
 * 앱은 막대 껍데기(밀대·정도·닫기)만 처음부터 갖고, 이 조각을 받으면 방식 단추·방향 단추와 단계 글을 막대에 끼운다.
 * 방향 단추는 한 라디오 묶음 안에 장면 축(사방·X·Y·Z)과 화면 방향(가로·세로·가로세로 — 보는 방향에 수직인 축) 두 칸으로 나눠
 * 휴대폰 폭에서는 화면 칸이 다음 줄로 내려간다.
 * 손질 칸(35차): "옮기기"(켜면 부품을 바로 끌어 분해 자리를 손질 — 손가락은 켜지 않아도 길게 눌러 끈다), 손질이 있으면 "되돌리기"(한 단계)·"모두 되돌리기".
 * 38차: 되돌린 것이 있으면 "다시 하기"(Ctrl/⌘+Shift+Z·Ctrl+Y), 옮기기 옆 "…"(손질 파일) 메뉴에 손질 내보내기(JSON)·불러오기.
 * 되돌리기·다시 하기 칸과 모두 되돌리기 칸은 따로 묶어 좁은 막대에서는 차례로 다음 줄로 내려간다.
 * 43차: 막 끈 뒤와 끄는 동안 쳐 넣기 시작하면 거리 칸("거리 [ ] mm" — 그 끌기로 옮긴 거리, 쳐 넣고 Enter·칸을 떠나면 그 거리로 맞춘다)을 손질 칸 끝에 둔다
 * (좁은 막대에서는 다음 줄로 — 손가락 기기는 이 칸을 눌러 쳐 넣는다). 45차: 끌지 않고 고른 것을 옮기려고 열면(Enter·작업 메뉴) 빈 칸.
 * 손질 도구(explodetool.ts — 손질 계산 explodetweak.ts·끌기 손짓 explodedrag.ts·손질 파일 explodefile.ts를 품는다)도 이 조각으로 받는다(앱은 이 모듈에서 꺼내 쓴다 — 첫 화면 JS 밖).
 * 48차: 옮기기 옆 "붙잡기" 누름 단추(기본 켬) — 끄면 끄는 동안 다른 부품 면에 붙지 않는다. 마우스의 Alt/⌥(누르는 동안만)와 달리 글쇠가 없는
 * 손가락 기기에서도 끄고 켤 수 있다(데스크톱 CAD의 수식 글쇠를 화면 단추로 옮긴 꼴 — SketchUp for iPad의 도구 방식, Fusion의 아래 막대 붙잡기 메뉴).
 * 끄는 동안 다른 손가락으로 눌러도 그 자리에서 바로 다시 본다.
 */
import type { Scene3d } from 'opencad-viewer3d/types';
import type { StepDoc } from './doc';
import { h, icon } from './dom';
import { EXPLODE_SCALE, explodeMoves, explodePlan, explodeStage, isScreenAxis, type ExplodeAxis, type ExplodeMode, type ExplodePlan, type ExplodeView } from './explode';
import type { ExplodeTweaks } from './explodetweak';
import { openMenu } from './menu';

export { ExplodeTweakTool } from './explodetool';

/** 화면 방향을 정한 카메라 각의 열쇠(같은 각이면 같은 계획) */
const viewKey = (v: ExplodeView | null | undefined) => (v ? `${v.yaw},${v.pitch}` : '0,0');

/**
 * 거리 칸 상태(43차): 그 끌기로 옮긴 거리(표시 단위, 점 소수), 단위 글, 분해 방향(받는 꼴 설명), 끄는 중인지.
 * fresh(45차): 끌지 않고 고른 것을 옮기려고 연 빈 칸 — 사방·화면 평면은 성분(쌍반점·음수 기호)을 쳐 넣어야 해 손가락 기기에 숫자 자판 대신 글 자판
 */
export interface DistState {
  value: string;
  unit: string;
  axis: ExplodeAxis;
  live: boolean;
  fresh?: boolean;
}

/**
 * 손질 도구가 거리 칸에 부르는 것: 상태 보이기(null = 숨기기), 그 글자로 쳐 넣기 시작(끄는 동안 숫자 글쇠), 칸에 들어가기(막 끈 뒤 Enter).
 * seed·focus는 칸이 보여 들어갔으면 true
 */
export interface DistField {
  show(s: DistState | null): void;
  seed(ch: string): boolean;
  focus(): boolean;
}

/** 손질 칸 알림(옮기기 켜고 끄기·한 단계 되돌리기·다시 하기·모두 되돌리기, 손질 파일 내보내기·불러오기, 쳐 넣은 거리·거리 칸 달기) */
export interface TweakHandlers {
  move: (on: boolean) => void;
  /** 붙잡기 켜고 끄기(48차) */
  snap: (on: boolean) => void;
  undo: () => void;
  redo: () => void;
  reset: () => void;
  exportFile: () => void;
  pickFile: () => void;
  /** 쳐 넣은 거리로 이번 끌기를 맞춘다(맞췄으면 true) */
  typed: (text: string) => boolean;
  /** 거리 칸을 단다 */
  bind: (f: DistField) => void;
}

/** 손질 칸 상태 */
export interface TweakState {
  /** 옮기기(바로 끌기)를 켰는지 */
  on: boolean;
  /** 붙잡기를 껐는지(48차 — 없으면 켬) */
  snapOff?: boolean;
  /** 지금 방향에서 손질한 단위 수 */
  count: number;
  /** 되돌릴 단계가 있는지 */
  undo: boolean;
  /** 다시 할 단계가 있는지 */
  redo?: boolean;
  /** 어느 방향에든 손질이 있는지(손질 파일로 내보낼 것) */
  any?: boolean;
  /** 거리 칸(막 끈 뒤와 끄는 동안 쳐 넣기 시작한 뒤에만 — 없으면 숨긴다) */
  dist?: DistState | null;
}

/** 거리 칸 설명(방향마다 받는 꼴) */
const DIST_TITLES = {
  line: '옮긴 거리 — 수를 쳐 넣고 Enter를 누르면 이번 끌기를 그 거리로 맞춥니다(음수는 반대쪽)',
  sp: '옮긴 거리 — 수를 쳐 넣고 Enter를 누르면 이번 끌기를 그 거리로 맞춥니다(가로; 세로 두 수도 됩니다)',
  free: '옮긴 거리 — 수를 쳐 넣고 Enter를 누르면 이번 끌기를 그 거리로 맞춥니다(ΔX; ΔY; ΔZ 세 수도 됩니다)',
} as const;

/** 선 아이콘(16px, 24 격자 경로) */
function lineIcon(d: string): SVGSVGElement {
  const t = document.createElement('template');
  t.innerHTML = `<svg class="icon" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="${d}"/></svg>`;
  return t.content.firstElementChild as SVGSVGElement;
}
/** 네 방향 화살표(옮기기) */
const MOVE_PATH = 'M12 3v18M3 12h18M9.5 5.5 12 3l2.5 2.5M9.5 18.5 12 21l2.5-2.5M5.5 9.5 3 12l2.5 2.5M18.5 9.5 21 12l-2.5 2.5';
/** 붙잡기: 큰 블록 면에 작은 블록이 맞닿은 꼴 */
const SNAP_PATH = 'M3 6h9v12H3zM12 9h9v6h-9';

/** 붙잡기 단추 설명(켜짐·꺼짐) */
const SNAP_TITLES = {
  on: '붙잡기 켬: 끄는 부품이 다른 부품 면에 닿거나 같은 높이가 되는 자리에 붙습니다 — 눌러서 끄기(마우스는 끄는 동안 Alt/⌥를 누르고 있으면 잠시 풉니다)',
  off: '붙잡기 끔: 끄는 부품이 다른 부품 면에 붙지 않습니다 — 눌러서 켜기',
} as const;

export class ExplodeControls {
  /** 방식 단추 묶음·방향 단추 묶음과 단계 글, 손질 칸(막대의 .explode-opts에 넣는다) */
  readonly els: HTMLElement[];
  private readonly btns = new Map<ExplodeMode, HTMLButtonElement>();
  private readonly axisBtns = new Map<ExplodeAxis, HTMLButtonElement>();
  private readonly stage: HTMLElement;
  private readonly moveBtn: HTMLButtonElement;
  /** 붙잡기 누름 단추(48차) */
  private readonly snapBtn: HTMLButtonElement;
  private readonly undoBtn: HTMLButtonElement;
  private readonly redoBtn: HTMLButtonElement;
  private readonly resetBtn: HTMLButtonElement;
  private readonly undoSeg: HTMLElement;
  private readonly resetSeg: HTMLElement;
  /** 거리 칸(43차): 칸 묶음·숫자 칸·단위 글, 마지막으로 보인 값과 마지막으로 건 글(칸을 떠날 때 두 번 걸지 않게) */
  private readonly distSeg: HTMLElement;
  private readonly distInput: HTMLInputElement;
  private readonly distUnit: HTMLElement;
  private distShown = '';
  private distSent: string | null = null;
  /** 어느 방향에든 손질이 있는지(손질 파일 메뉴의 내보내기) — 마지막 sync 것 */
  private anyTweak = false;
  /** 장면·방식·방향마다 계획(묶음 범위를 한 번만 잰다 — 밀대를 움직일 때는 곱하기만). 화면 방향은 마지막 카메라 각 것만 둔다 */
  private readonly plans = new WeakMap<Scene3d, Map<string, ExplodePlan>>();

  constructor(onMode: (mode: ExplodeMode) => void, onAxis: (axis: ExplodeAxis) => void = () => {}, tweak: Partial<TweakHandlers> = {}) {
    const seg = h('div', { class: 'seg explode-modes', role: 'radiogroup', 'aria-label': '분해 방식' });
    for (const [k, label, title] of [
      ['step', '단계별', '조립 단계별: 바깥 조립부터 벌립니다 — 하위 조립을 통째로 먼저 떼고, 더 밀면 그 안의 부품을 벌립니다'],
      ['all', '한꺼번에', '한꺼번에: 모든 부품을 조립 가운데에서 함께 벌립니다'],
    ] as const) {
      const b = h('button', { type: 'button', class: 'seg-btn', role: 'radio', 'aria-checked': 'false', title }, label);
      b.addEventListener('click', () => onMode(k));
      this.btns.set(k, b);
      seg.append(b);
    }
    const axes = h('div', { class: 'explode-axes', role: 'radiogroup', 'aria-label': '분해 방향' });
    const world = h('div', { class: 'seg' });
    const screen = h('div', { class: 'seg' });
    const AIM = '분해를 켜거나 이 단추를 누를 때의 카메라로 정하고, 다시 누르면 지금 카메라로 다시 맞춥니다';
    for (const [k, label, title, name, into] of [
      ['free', '사방', '사방: 부품이 조립 가운데에서 멀어지는 쪽으로 벌립니다', '', world],
      ['x', 'X', 'X축으로만: 부품을 X축 방향으로만 벌립니다', '', world],
      ['y', 'Y', 'Y축으로만: 부품을 Y축 방향으로만 벌립니다', '', world],
      ['z', 'Z', 'Z축으로만: 부품을 Z축 방향으로만 벌립니다', '', world],
      ['sx', '가로', `화면 가로로만: 부품을 지금 화면의 가로 방향으로만 벌립니다 — ${AIM}`, '화면 가로', screen],
      ['sy', '세로', `화면 세로로만: 부품을 지금 화면의 세로 방향으로만 벌립니다 — ${AIM}`, '화면 세로', screen],
      ['sp', '가로세로', `화면 평면: 부품을 보는 방향에 수직인 화면 가로·세로로만 벌립니다 — ${AIM}`, '화면 평면', screen],
    ] as const) {
      const b = h('button', { type: 'button', class: 'seg-btn', role: 'radio', 'aria-checked': 'false', title, ...(name ? { 'aria-label': name } : {}) }, label);
      b.addEventListener('click', () => onAxis(k));
      this.axisBtns.set(k, b);
      into.append(b);
    }
    axes.append(world, h('span', { class: 'explode-screen' }, h('span', { class: 'explode-screen-label', 'aria-hidden': 'true' }, '화면'), screen));
    this.stage = h('span', { class: 'explode-stage', hidden: true });
    // 손질 칸: 옮기기(누름 단추) · 되돌리기 · 모두 되돌리기(손질이 있을 때만)
    this.moveBtn = h(
      'button',
      { type: 'button', class: 'seg-btn explode-move', 'aria-pressed': 'false', title: '옮기기: 켜면 부품을 끌어 분해 자리를 손질합니다(손가락은 켜지 않아도 길게 누른 채 끕니다)' },
      lineIcon(MOVE_PATH),
      h('span', {}, '옮기기'),
    );
    this.moveBtn.addEventListener('click', () => tweak.move?.(this.moveBtn.getAttribute('aria-pressed') !== 'true'));
    this.snapBtn = h('button', { type: 'button', class: 'seg-btn explode-snap on', 'aria-pressed': 'true', title: SNAP_TITLES.on }, lineIcon(SNAP_PATH), h('span', {}, '붙잡기'));
    // 누르면 단추도 바로 맞춘다(막대 sync는 끄는 동안 부르지 않는다 — 다른 손가락으로 누른 때)
    const toggle = (): void => {
      const off = this.snapBtn.getAttribute('aria-pressed') === 'true';
      tweak.snap?.(!off);
      this.showSnap(off);
    };
    // 첫 손가락으로 끄는 동안 둘째 손가락으로 누르면 브라우저가 누르기(click)를 내지 않아(두 손가락 몸짓) 뗄 때 바로 바꾸고, 뒤따르는 click이 있으면 한 번 거른다
    let touched = -1;
    this.snapBtn.addEventListener('pointerup', (e) => {
      if (e.pointerType !== 'touch' || e.isPrimary) return;
      touched = e.timeStamp;
      toggle();
    });
    this.snapBtn.addEventListener('click', (e) => {
      if (touched >= 0 && e.timeStamp - touched < 800) touched = -1;
      else toggle();
    });
    // 손질 파일(…): 내보내기(JSON — 손질이 있을 때)·불러오기 메뉴
    const fileBtn = h(
      'button',
      { type: 'button', class: 'seg-btn explode-file-btn', 'aria-label': '손질 파일', 'aria-haspopup': 'menu', title: '손질 파일: 분해 손질을 JSON 파일로 내보내거나 불러옵니다' },
      icon('more', 16),
    );
    fileBtn.addEventListener('click', () =>
      openMenu(
        fileBtn,
        [
          { label: '손질 내보내기(JSON 파일)', disabled: !this.anyTweak, run: () => tweak.exportFile?.() },
          { label: '손질 불러오기…', run: () => tweak.pickFile?.() },
        ],
        '손질 파일',
      ),
    );
    this.undoBtn = h('button', { type: 'button', class: 'seg-btn explode-undo', title: '손질 한 단계 되돌리기 (Ctrl+Z)', hidden: true }, icon('reset', 14), h('span', {}, '되돌리기'));
    this.undoBtn.addEventListener('click', () => tweak.undo?.());
    this.redoBtn = h('button', { type: 'button', class: 'seg-btn explode-redo', title: '되돌린 손질 한 단계 다시 하기 (Ctrl+Shift+Z)', hidden: true }, icon('reset', 14), h('span', {}, '다시 하기'));
    this.redoBtn.addEventListener('click', () => tweak.redo?.());
    this.resetBtn = h('button', { type: 'button', class: 'seg-btn explode-reset', title: '손질을 모두 지우고 계획 자리로', hidden: true }, '모두 되돌리기');
    this.resetBtn.addEventListener('click', () => tweak.reset?.());
    // 옮기기·되돌리기·모두 되돌리기 칸은 따로 묶어 좁은 막대에서는 다음 줄로 내려간다(긴 번역 — 독일어 등)
    this.undoSeg = h('div', { class: 'seg', hidden: true }, this.undoBtn, this.redoBtn);
    this.resetSeg = h('div', { class: 'seg', hidden: true }, this.resetBtn);
    // 거리 칸(막 끈 뒤·끄는 동안 쳐 넣기 시작하면): 점 소수 숫자(언어와 상관없이 — 쉼표 소수 언어는 쉼표도 받는다), 손가락 기기는 숫자 자판
    this.distInput = h('input', {
      type: 'text',
      class: 'explode-num',
      inputmode: 'decimal',
      enterkeyhint: 'done',
      autocomplete: 'off',
      spellcheck: 'false',
      'aria-label': '옮긴 거리(숫자)',
      title: DIST_TITLES.free,
    });
    this.distUnit = h('span', { class: 'explode-unit' });
    this.distSeg = h('label', { class: 'explode-distance', hidden: true }, h('span', { class: 'explode-distance-key' }, '거리'), this.distInput, this.distUnit);
    const send = (): void => {
      const text = this.distInput.value;
      if (text === this.distShown || text === this.distSent) return;
      this.distSent = text;
      if (tweak.typed?.(text)) {
        this.distInput.blur();
        this.distInput.value = this.distShown;
      } else if (document.activeElement === this.distInput) this.distInput.select();
      else this.distInput.value = this.distShown;
    };
    this.distInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        this.distSent = null;
        send();
      }
      // 칸의 Esc는 칸만(쳐 넣던 것을 버리고 나온다 — 끄는 중이면 끌기는 그대로, 한 번 더 누르면 끌기 취소)
      if (e.key === 'Escape') {
        e.preventDefault();
        e.stopPropagation();
        this.distInput.value = this.distShown;
        this.distInput.blur();
      }
    });
    // 칸을 떠나면 바뀐 글을 건다(손가락 기기의 숫자 자판에는 Enter가 없다). 걸지 못한 글은 떠난 뒤 보일 값으로 되돌린다
    this.distInput.addEventListener('change', send);
    this.distInput.addEventListener('focus', () => (this.distSent = null));
    this.distInput.addEventListener('blur', () => {
      if (this.distInput.value !== this.distShown) this.distInput.value = this.distShown;
    });
    const field: DistField = {
      show: (s) => this.showDistance(s),
      seed: (ch) => {
        if (this.distSeg.hidden) return false;
        this.distInput.value = ch;
        this.distInput.focus();
        try {
          this.distInput.setSelectionRange(ch.length, ch.length);
        } catch {
          /* 선택을 못 하는 칸 */
        }
        return true;
      },
      focus: () => {
        if (this.distSeg.hidden) return false;
        this.distInput.focus();
        this.distInput.select();
        return true;
      },
    };
    tweak.bind?.(field);
    const tw = h('div', { class: 'explode-tweak', role: 'group', 'aria-label': '분해 손질' }, h('div', { class: 'seg' }, this.moveBtn, this.snapBtn, fileBtn), this.undoSeg, this.resetSeg, this.distSeg);
    this.els = [seg, axes, this.stage, tw];
  }

  /** 붙잡기 단추 맞추기. 설명은 켜짐이 바뀔 때만 다시 건다(번역층이 옮긴 글을 sync마다 덮지 않게) */
  private showSnap(off: boolean): void {
    const pressed = String(!off);
    if (this.snapBtn.getAttribute('aria-pressed') === pressed) return;
    this.snapBtn.classList.toggle('on', !off);
    this.snapBtn.setAttribute('aria-pressed', pressed);
    this.snapBtn.title = SNAP_TITLES[off ? 'off' : 'on'];
  }

  /** 거리 칸 맞추기(null = 숨기기). 쳐 넣는 중(칸에 초점)이면 글은 그대로 두고 보일 값만 기억한다 */
  private showDistance(s: DistState | null): void {
    this.distSeg.hidden = !s;
    if (!s) {
      this.distShown = '';
      return;
    }
    this.distShown = s.value;
    if (document.activeElement !== this.distInput) this.distInput.value = s.value;
    this.distUnit.textContent = s.unit;
    this.distUnit.hidden = !s.unit;
    const kind = s.axis === 'sp' || s.axis === 'free' ? s.axis : 'line';
    const title = DIST_TITLES[kind];
    if (this.distInput.title !== title) this.distInput.title = title;
    this.distInput.setAttribute('inputmode', s.fresh && kind !== 'line' ? 'text' : 'decimal');
  }

  /** 문서·방식·방향의 분해 계획(표현 PMI는 제자리). 화면 방향은 view(카메라 각)로 */
  plan(d: StepDoc, mode: ExplodeMode, axis: ExplodeAxis = 'free', view?: ExplodeView | null): ExplodePlan {
    let plans = this.plans.get(d.scene);
    if (!plans) this.plans.set(d.scene, (plans = new Map()));
    const head = `${mode}:${axis}`;
    const key = isScreenAxis(axis) ? `${head}:${viewKey(view)}` : head;
    let p = plans.get(key);
    if (!p) {
      const fixed = d.vis.pmiIds;
      p = explodePlan(
        [...d.scene.meshes, ...d.scene.lines, ...(d.scene.points ?? [])].filter((x) => !fixed.has(x.id)),
        d.products,
        mode,
        axis,
        view ? { view } : {},
      );
      // 화면 방향은 카메라 각마다 계획이 달라 앞 각의 것은 버린다(다시 맞출 때마다 쌓이지 않게)
      if (key !== head) for (const k of [...plans.keys()]) if (k.startsWith(`${head}:`)) plans.delete(k);
      plans.set(key, p);
    }
    return p;
  }

  /** 분해 정도 t(0~1)에서 묶음마다 옮길 양(손질이 있으면 그 방향의 덧이동을 더한다) */
  moves(d: StepDoc, mode: ExplodeMode, t: number, axis: ExplodeAxis = 'free', view?: ExplodeView | null, tweaks?: ExplodeTweaks | null): Map<string, [number, number, number]> {
    const plan = this.plan(d, mode, axis, view);
    return explodeMoves(plan, t, EXPLODE_SCALE, tweaks?.count(axis) ? tweaks.resolve(plan, axis, plan.view) : undefined);
  }

  /**
   * 방식·방향 단추와 단계 글 맞추기: 조립 단계별이고 단계가 둘 이상이면 "단계 2/3"(지금 벌리는 단계 — 방향을 고르면 그 방향으로 움직이는 단계만 센다).
   * 막대가 닫혀 있으면 계획을 세우지 않는다(큰 모형에서 문서를 열 때 범위를 재지 않게). 손질 칸은 tweak 상태대로
   */
  sync(d: StepDoc | null, mode: ExplodeMode, open: boolean, axis: ExplodeAxis = 'free', view?: ExplodeView | null, tweak?: TweakState): void {
    const tw = tweak ?? { on: false, count: 0, undo: false };
    this.moveBtn.classList.toggle('on', tw.on);
    this.moveBtn.setAttribute('aria-pressed', String(tw.on));
    this.showSnap(!!tw.snapOff);
    this.undoBtn.hidden = !tw.undo;
    this.redoBtn.hidden = !tw.redo;
    this.resetBtn.hidden = !tw.count;
    this.undoSeg.hidden = !tw.undo && !tw.redo;
    this.resetSeg.hidden = !tw.count;
    this.anyTweak = !!tw.any;
    this.showDistance(open ? (tw.dist ?? null) : null);
    for (const [k, b] of this.btns) {
      b.classList.toggle('on', k === mode);
      b.setAttribute('aria-checked', String(k === mode));
    }
    for (const [k, b] of this.axisBtns) {
      b.classList.toggle('on', k === axis);
      b.setAttribute('aria-checked', String(k === axis));
    }
    const plan = d && open && mode === 'step' ? this.plan(d, mode, axis, view) : null;
    const levels = plan?.levels ?? 0;
    this.stage.hidden = levels < 2;
    if (plan && levels >= 2) this.stage.textContent = `단계 ${explodeStage(plan, d!.explode)}/${levels}`;
  }
}
